import { randomUUID } from 'node:crypto';
import type request from 'supertest';
import { TEST_ITEM } from './test-item.record.js';
import { fieldSamples } from '../../../src/platform/fields/fields.js';
import { describeCapabilities } from '../../record-capabilities.js';
import { bootApp, type TestApp } from '../../support.js';

/**
 * Test items: the standard routes, on bodies from the declaration (fieldSamples):
 * a field added later is covered. Generated by `pnpm feature:add` (tools/feature): add the feature's own rules as tests here.
 */
describe('test items (e2e)', () => {
  let node: TestApp;

  beforeEach(async () => {
    node = await bootApp();
  });
  afterEach(() => node.close());

  const samples = fieldSamples(TEST_ITEM.fields);
  /** A change of one field. */
  const changed = samples.changed;
  const create = (
    agent: request.Agent,
    key = randomUUID(),
    sent = samples.body(),
  ) => agent.post('/v1/test-items').set('Idempotency-Key', key).send(sent);

  it('creates once per Idempotency-Key, changes with If-Match (audited), deletes', async () => {
    const admin = node.admin();
    const key = randomUUID();
    const sent = samples.body();
    const created = await create(admin, key, sent).expect(201);
    const id = created.body.id as string;
    // The same key again: the first answer, not a second record.
    expect((await create(admin, key, sent)).body.id).toBe(id);

    const shown = await admin.get(`/v1/test-items/${id}`).expect(200);
    const etag = shown.headers.etag as string;
    const updated = await admin
      .patch(`/v1/test-items/${id}`)
      .set('If-Match', etag)
      .send(changed)
      .expect(200);
    expect(updated.body[samples.changedField]).toEqual(
      changed[samples.changedField],
    );
    // The ETag read before the change no longer matches.
    await admin
      .patch(`/v1/test-items/${id}`)
      .set('If-Match', etag)
      .send(changed)
      .expect(412);
    const actions = (await node.auditEntries({ targetId: id })).map(
      (entry) => entry.action,
    );
    expect(actions).toEqual(
      expect.arrayContaining(['testItem.created', 'testItem.updated']),
    );

    await admin.delete(`/v1/test-items/${id}`).expect(204);
    await admin.get(`/v1/test-items/${id}`).expect(404);
    // The recycle bin: back until the purge.
    await admin.post(`/v1/test-items/${id}/restore`).expect(200);
    await admin.get(`/v1/test-items/${id}`).expect(200);
  });

  it('refuses a body that fails the schema', async () => {
    await node
      .admin()
      .post('/v1/test-items')
      .set('Idempotency-Key', randomUUID())
      .send({ ...samples.body(), ...samples.invalid })
      .expect(400);
  });

  it('lets each role do what it grants: editors their own, viewers read', async () => {
    const writer = await node.user(['editor']);
    const other = await node.user(['editor']);
    const viewer = await node.user(['viewer']);
    const id = (await create(writer.agent).expect(201)).body.id as string;
    await other.agent.get(`/v1/test-items/${id}`).expect(403);
    expect(
      (await other.agent.get('/v1/test-items').expect(200)).body.items,
    ).toEqual([]);
    await viewer.agent.get(`/v1/test-items/${id}`).expect(200);
    await create(viewer.agent).expect(403);
  });

  it('keeps tenants apart', async () => {
    const id = (await create(node.admin()).expect(201)).body.id as string;
    const other = await node.otherTenant();
    await other.admin.get(`/v1/test-items/${id}`).expect(404);
  });

  it('lists newest first', async () => {
    const admin = node.admin();
    await create(admin).expect(201);
    const newest = (await create(admin).expect(201)).body.id as string;
    const page = await admin
      .get('/v1/test-items?sort=-createdAt&limit=10')
      .expect(200);
    expect(page.body.items[0].id).toBe(newest);
    expect(page.body.items).toHaveLength(2);
  });

  // Each capability test-item.record.ts declares (record-capabilities.ts).
  describeCapabilities(() => node, TEST_ITEM);
});
